function normalize(str) {
  return String(str || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd')
    .replace(/Đ/g, 'D')
    .trim();
}

function getTelegramContext(source) {
  const payload = source.payload || {};
  const message = source.message || payload.message || payload.body?.message || {};
  const chatId = source.chatId || message.chat?.id || payload.chatId || '';
  const rawText = String(
    source.rawText ||
    source.text ||
    message.text ||
    message.caption ||
    payload.text ||
    payload.rawText ||
    ''
  ).trim();

  return { payload, message, chatId, rawText };
}

const source = $input.item.json || {};
const ctx = getTelegramContext(source);
const text = normalize(ctx.rawText);
const hasAny = (keywords) => keywords.some((k) => text.includes(k));

let action = 'help';

if (hasAny(['docs help', 'google docs help', 'huong dan docs', 'huong dan google docs', 'doc help'])) {
  action = 'help';
} else if (hasAny(['tao doc', 'tao tai lieu', 'create doc'])) {
  action = 'create_doc';
} else if (hasAny(['them vao doc', 'append doc', 'ghi them vao tai lieu'])) {
  action = 'append_doc';
} else if (hasAny(['doc doc', 'xem doc', 'noi dung doc', 'read doc'])) {
  action = 'read_doc';
} else if (hasAny(['tim doc', 'search doc', 'tim tai lieu'])) {
  action = 'search_doc';
} else if (hasAny(['xoa doc', 'delete doc', 'xoa tai lieu'])) {
  action = 'delete_doc';
}

return [{
  json: {
    ...source,
    payload: ctx.payload,
    message: ctx.message,
    chatId: ctx.chatId,
    rawText: ctx.rawText,
    text,
    action
  }
}];

const workflowMap = {
  create_doc: 'Sub-workflow: Google Docs - Create Doc',
  read_doc: 'Sub-workflow: Google Docs - Read Doc',
  append_doc: 'Sub-workflow: Google Docs - Append Doc',
  search_doc: 'Sub-workflow: Google Docs - Search Doc',
  delete_doc: 'Sub-workflow: Google Docs - Delete Doc',
  help: 'Sub-workflow: Google Docs - Help'
};

return [{ json: { ...$json, workflowName: workflowMap[$json.action] || workflowMap.help } }];

const workflows = $input.item.json.data || [];
const source = $('Chon Workflow Docs').item.json || {};
const found = workflows.find((workflow) => workflow.name === source.workflowName);
if (!found) {
  return [{ json: { ...source, hasWorkflow: false, response: 'Khong tim thay workflow con: ' + source.workflowName } }];
}
return [{ json: { ...source, hasWorkflow: true, workflowId: found.id } }];
